def check_pages(pages, total_ids):
    seen, dupes = set(), set()
    for page in pages:
        for i in page:
            if i in seen:
                dupes.add(i)
            seen.add(i)
    return {'duplicates': sorted(dupes), 'missing': sorted(set(total_ids) - seen), 'unexpected': sorted(seen - set(total_ids))}

