coding.solution:
def _cmp(a, b, keys):
    for k in keys:
        desc = k.startswith('-')
        name = k.lstrip('-')
        x, y = a[name], b[name]
        if x == y:
            continue
        if desc:
            return -1 if x > y else 1
        return -1 if x < y else 1
    return 0

def sort_violations(items, keys):
    return [i for i in range(len(items) - 1) if _cmp(items[i], items[i + 1], keys) > 0]
